/* FASE 42 · DIRECTOR DE MISIONES — objetivo y reglas reales, no solo textos cambiados.
   Los 200 niveles mantienen sus jefes, guardado y números originales. */
const GG42_VARIETY_MODES=[
 {id:'patrol',name:'PATRULLA TÁCTICA',desc:'Elimina las formaciones y aprende a reconocer sus ataques.',tip:'Mantén tu nave en movimiento y aprovecha los huecos.'},
 {id:'flank',name:'ASALTO DE FLANCOS',desc:'Ataques coordinados desde ambos laterales; vigila las entradas.',tip:'Alterna entre izquierda y derecha para cubrir los flancos.'},
 {id:'intercept',name:'INTERCEPCIÓN',desc:'Cazas veloces intentarán cruzar la zona. Derríbalos antes de escapar.',tip:'Abate los interceptores marcados para ganar bonificaciones.'},
 {id:'leader',name:'CAZA DEL COMANDANTE',desc:'Un líder reforzado coordina el grupo: derríbalo y desorganizarás la oleada.',tip:'Prioriza la nave marcada con el aro dorado.'},
 {id:'ambush',name:'EMBOSCADA ESCALONADA',desc:'Los enemigos aparecen por tandas: reserva espacio para los refuerzos.',tip:'No te confíes después de la primera entrada.'},
 {id:'supply',name:'CORREDOR DE SUMINISTROS',desc:'Un transportista enemigo lleva recursos: derríbalo para recoger una mejora.',tip:'Busca la nave con el aro verde y recoge su carga.'},
 {id:'morph',name:'FORMACIÓN CAMBIANTE',desc:'Los escuadrones cambian de figura durante la batalla.',tip:'Anticípate al reagrupamiento de las naves.'},
 {id:'gauntlet',name:'CAZA DE INCURSORES',desc:'Pequeños cazas realizan picados mientras el resto cubre la formación.',tip:'Esquiva los picados y contraataca cuando se alejen.'},
 {id:'boss',name:'ENCUENTRO DE JEFE',desc:'Supera las oleadas y derrota al comandante del sector.',tip:'Observa los avisos antes de cada ataque del jefe.'}
];
function gg42MissionMode(level){
 const m=MISSION_SCRIPTS[Math.max(0,Math.min(199,level-1))];
 if(m.jefe)return GG42_VARIETY_MODES[8];
 if(level===1)return GG42_VARIETY_MODES[0];
 return GG42_VARIETY_MODES[1+((m.local*3+Math.floor(m.local/3)+m.mundo*5)%7)];
}
for(const m of MISSION_SCRIPTS){
 const mode=gg42MissionMode(m.nivel);m.gg42Mode=mode.id;
 m.objetivo_exacto=mode.desc;
 m.nombre=mode.name+' · '+String(m.local).padStart(2,'0');
}
function gg42MissionBonus(r,coins,message){r.earned+=coins;r.score+=coins*14;r.gg42Bonus=(r.gg42Bonus||0)+coins;announce(message+' · +'+coins+' MONEDAS',1.8);}
/* FASE 55.4 · lectura visual de la amenaza y recompensas coherentes. */
const GG57_TIERS=[
 {name:'DÉBIL',color:'#69dfff',symbol:'●'},
 {name:'MEDIO',color:'#ffd475',symbol:'◆'},
 {name:'FUERTE',color:'#ff947b',symbol:'▲'},
 {name:'ÉLITE',color:'#e1a9ff',symbol:'★'}
];
function gg57EnemyTier(e){
 if(e.gg42Captain||e.gg56Ace||e.isLeader)return GG57_TIERS[3];
 return GG57_TIERS[(e.gg58New??e.type)<=1?0:(e.gg58New??e.type)===2?1:3];
}
function gg57TrySpawnReward(item,priority=false){
 if(!run)return false;
 const r=run,visible=drops.filter(d=>!d.collected&&d.y<H+50);
 if(visible.length>=3)return false;
 const gap=priority?2.3:4.7;
 if(r.elapsed-(r.gg57LastDropAt??-100)<gap)return false;
 if(item.kind==='secondary'&&visible.some(d=>d.kind==='secondary'))return false;
 drops.push({...item,age:0,phase:Math.random()*6.28});
 r.gg57LastDropAt=r.elapsed;
 GG_COMBAT_TELEMETRY.dropsCreated++;
 return true;
}
function gg42OnKill(e){
 if(!run)return;const r=run;
 // Encadenar bajas recompensa la destreza sin aumentar el daño infligido.
 r.gg42Combo=r.elapsed-(r.gg42LastKill??-100)<2.4?Math.min(8,(r.gg42Combo||0)+1):1;
 r.gg42LastKill=r.elapsed;
 if(r.gg42Combo>=3){r.score+=r.gg42Combo*8;r.earned+=1;if(r.gg42Combo===5)announce('¡COMBO DE CINCO! · BONUS DE PUNTOS',1.1);}
 if(e.gg42Runner){r.gg42Intercepts=(r.gg42Intercepts||0)+1;if(!e.gg42BonusPaid){e.gg42BonusPaid=true;gg42MissionBonus(r,12,'INTERCEPTOR ABATIDO');}}
 if(e.gg42Captain&&!e.gg42BonusPaid){e.gg42BonusPaid=true;gg42MissionBonus(r,32,'COMANDANTE NEUTRALIZADO');}
 if(e.gg42Cargo&&!e.gg42BonusPaid){
   e.gg42BonusPaid=true;gg42MissionBonus(r,22,'TRANSPORTE INTERCEPTADO');
   gg57TrySpawnReward({x:clamp(e.x,60,W-60),y:e.y,kind:r.weapon<GG40_MAX_POWER?'weapon':'shield',slot:null,gg42Cargo:true},true);
 }
 gg56OnKill(e);
}

/* FASE 55.1 — EVENTOS DE SECTOR. No reemplazan las 9 modalidades de misión.
   Todos los eventos son opcionales; no retrasan la salida de una oleada.
   Calendario determinista para evitar repeticiones aleatorias y poder probarlos. */
const GG56_EVENTS=[
 {id:'supply',name:'CORREDOR DE APOYO',tip:'Recoge un suministro durante el combate.'},
 {id:'ace',name:'PILOTO DE ÉLITE',tip:'Derrota al as marcado para cobrar la recompensa.'},
 {id:'courier',name:'CARGAMENTO SECRETO',tip:'Intercepta el transporte para conseguir una mejora.'},
 {id:'shift',name:'REAGRUPAMIENTO SORPRESA',tip:'Atención: el enemigo cambiará de formación.'},
 {id:'intercept',name:'CAZAS FUGITIVOS',tip:'Alcanza a los interceptores antes de que escapen.'},
 {id:'recharge',name:'VENTANA DE RECARGA',tip:'El sistema repara escudos y recarga energía.'},
 {id:'combo',name:'DESAFÍO DE RÁFAGA',tip:'Elimina 4 enemigos en 18 segundos para ganar monedas.'}
];
function gg56EventIndex(level,wave){return (level*17+wave*13+Math.floor((level-1)/20)*3)%GG56_EVENTS.length;}
function gg56SectorEvent(r,waveFoes,waveIndex){
 // La primera oleada sigue siendo de calentamiento; después, cada oleada trae un evento rotatorio.
 if(r.local<4||!waveFoes.length||waveIndex<1)return;
 const e=GG56_EVENTS[gg56EventIndex(r.level,waveIndex)];
 r.gg56Event=e.id;r.gg56EventLabel=e.name;r.gg56EventTip=e.tip;r.gg56EventUntil=r.elapsed+13;
 r.gg56EventsSeen=(r.gg56EventsSeen||0)+1;
 const chosen=waveFoes[Math.floor(waveFoes.length/2)];
 switch(e.id){
  case 'supply':{
    const kind=r.weapon<GG40_MAX_POWER?'weapon':r.shield<5?'shield':'energy';
    gg57TrySpawnReward({x:clamp(r.px+((r.wave%2)?-110:110),70,W-70),y:180,kind,gg56Event:true},true);
    break;
  }
  case 'ace':
    if(!chosen.gg42Captain&&!chosen.gg42Cargo&&!chosen.gg42Runner){
      chosen.gg42Captain=true;chosen.isLeader=true;chosen.hp=Math.ceil(chosen.hp*1.35);chosen.maxHp=chosen.hp;
      chosen.fire=Math.max(chosen.fire,2.0);
    }else{chosen.gg56Ace=true;}
    break;
  case 'courier':
    if(!chosen.gg42Captain&&!chosen.gg42Cargo&&!chosen.gg42Runner){chosen.gg42Cargo=true;chosen.hp=Math.ceil(chosen.hp*1.2);chosen.maxHp=chosen.hp;}
    else chosen.gg56Cargo=true;
    break;
  case 'shift':
    if(r.formationState){r.formationState.gg56ShiftAt=r.elapsed+4.2;r.formationState.gg56Shifted=false;}
    break;
  case 'intercept':
    for(const target of [waveFoes[0],waveFoes[Math.floor(waveFoes.length*.66)]]){
      if(!target.gg42Captain&&!target.gg42Cargo)target.gg42Runner=true;
      else target.gg56Runner=true;
    }
    break;
  case 'recharge':
    r.energy=Math.min(100,r.energy+40);
    r.shield=Math.min(6,r.shield+1);
    break;
  case 'combo':
    r.gg56Challenge={goal:4,kills:0,deadline:r.elapsed+18,paid:false};
    break;
 }
 announce('EVENTO DE SECTOR · '+e.name,2.0);
}
function gg56OnKill(e){
 if(!run)return;
 const r=run,c=r.gg56Challenge;
 if(e.gg56Ace&&!e.gg42BonusPaid){e.gg42BonusPaid=true;gg42MissionBonus(r,28,'AS DE ÉLITE');}
 if(e.gg56Cargo&&!e.gg42BonusPaid){e.gg42BonusPaid=true;gg42MissionBonus(r,22,'CARGAMENTO ESPECIAL');gg57TrySpawnReward({x:clamp(e.x,60,W-60),y:e.y,kind:r.weapon<GG40_MAX_POWER?'weapon':'shield',gg56Event:true},true);}
 if(e.gg56Runner&&!e.gg42BonusPaid){e.gg42BonusPaid=true;gg42MissionBonus(r,12,'CAZA FUGITIVA');}
 if(c&&!c.paid&&r.elapsed<=c.deadline){
   c.kills++;
   if(c.kills>=c.goal){c.paid=true;r.gg56ChallengesWon=(r.gg56ChallengesWon||0)+1;gg42MissionBonus(r,55,'DESAFÍO DE RÁFAGA COMPLETADO');}
 }
}
function gg56Tick(){
 if(!run||run.done)return;
 const r=run,fs=r.formationState;
 if(r.gg56Challenge&&!r.gg56Challenge.paid&&r.elapsed>r.gg56Challenge.deadline){
   r.gg56Challenge=null;
   if(r.gg56Event==='combo')r.gg56EventUntil=Math.min(r.gg56EventUntil||0,r.elapsed);
 }
 if(fs&&fs.gg56ShiftAt&&!fs.gg56Shifted&&r.elapsed>=fs.gg56ShiftAt&&foes.length){
   fs.gg56Shifted=true;
   const next=(fs.id+11+r.world)%FORMATIONS.length;
   for(const e of foes)if(e.group===fs.wave&&e.entryDuration){e.gg57PatternFrom=e.pattern;e.gg57MorphAt=e.age;e.pattern=next;e.disrupted=true;e.disruptedAt=e.age;}
   fs.id=next;fs.name=FORMATIONS[next].nombre;fs.nextDiveAt=r.elapsed+4.2;
   r.gg56Reforms=(r.gg56Reforms||0)+1;
   announce('¡REAGRUPAMIENTO! · '+fs.name.toUpperCase(),1.9);
 }
}

