function gg58SlotForWave(r,wave,index){
 // Fase 55.6: SOLO las 5 naves nuevas de cada planeta. Progresión sin modelos heredados.
 // En los primeros niveles se enseñan las dos naves débiles; luego las de mayor resistencia.
 const available=r.local<=2?2:r.local<=5?3:r.local<=9?4:5;
 return (index+Math.floor(index/3)+wave*2+r.local+r.world)%available;
}
function gg58ShootEnemy(e){
 if(!run)return;
 const slot=e.gg58New,world=e.world,asset=world*5+slot;
 const x=e.x,y=e.y+16;
 const speed=(139+world*11+slot*9)*difficulty().speed;
 const base=Math.atan2(Math.max(65,run.py-y),run.px-x);
 const aim=clamp(base,.22,Math.PI-.22);
 const kind=slot===0?'orb':slot===1?'needle':slot===2?'bolt':slot===3?'ring':world===6||world===8?'laser':'orb';
 const behavior=slot===3?'wave':slot===4?(world===7||world===8?'homing':'accelerate'):'normal';
 const n=slot<2?1:slot===2?2:slot===3?2:3;
 const spread=slot===2?.13:slot===3?.18:.115;
 for(let i=0;i<n;i++){
  const a=clamp(aim+(i-(n-1)/2)*spread,.21,Math.PI-.21);
  const before=enemyBullets.length;
  shot(x+(i-(n-1)/2)*6,y,Math.cos(a)*speed,Math.sin(a)*speed,false,kind,COLORS[world],slot>=3?6:4,slot>=4&&world>=4?2:1,behavior,null,null);
  for(let j=before;j<enemyBullets.length;j++){
    enemyBullets[j].gg58Weapon=asset;
    enemyBullets[j].gg58DrawSize=[42,45,49,54,58][slot];
  }
 }
}
