/* Fase 41.2 — Combate calibrado: el jugador no elimina enemigos normales de 2-3 impactos. */
const GAME_BALANCE={hp:[35,49,65,81,99,120,146],enemyDamage:[1,1,1,1,1,2,2],mainBase:9};
const GG412_BALANCE={version:'41.2',hpBase:[...GAME_BALANCE.hp],mainBase:GAME_BALANCE.mainBase,bossMultiplier:1.48,bossFinalExtra:1.10};
function gg412EnemyHP(world,type,local=1){
  const w=clamp(Math.floor(world),0,9),t=clamp(Math.floor(type),0,6),lv=clamp(Math.floor(local),1,20);
  // La resistencia aumenta con la misión, no con la potencia EQUIPADA. Mejorar el arma siempre ayuda.
  const worldScale=1+w*.055+Math.floor((lv-1)/10)*.055;
  const progressScale=1+(lv-1)*.032+Math.max(0,lv-10)*.022;
  const variation=1+(((w*7+t)%4)-1)*.025;
  return Math.max(1,Math.round(GAME_BALANCE.hp[t]*worldScale*progressScale*variation*difficulty().hp));
}
