/* Auditoría ejecutable: sin inventar cadencias del juego de referencia.
   Auditoría aplicada a la campaña activa de 200 misiones de Guardián Galáctico. */
function ggMissionAudit(level){
  const m=MISSION_SCRIPTS[level-1];if(!m)return null;
  return {level,world:m.mundo,waves:m.oleadas.length,enemies:m.oleadas.reduce((v,w)=>v+w.cantidad,0),
    boss:!!m.jefe,formations:new Set(m.oleadas.map(w=>w.formacion)).size,
    restSeconds:m.oleadas.map(w=>w.respiro_segundos),attackIntervals:m.oleadas.map(w=>w.intervalo_entre_ataques)};
}
