const defaultSave=()=>({lastUnlocked:1,lastPlayed:1,coins:250,selected:0,ships:[0,1,2,3,4],upgrades:{},worldWeaponLevels:Array(10).fill(1),campaignSchema:200,wins:0,bossWins:0,highestScore:0,perfect:0,difficulty:'normal'});let save=defaultSave();try{let s=JSON.parse(localStorage.getItem('GG_UNIVERSO_V3')||'null');if(s)save={...defaultSave(),...s,lastPlayed:Number.isInteger(s.lastPlayed)?s.lastPlayed:Math.min(s.campaignSchema===200?200:500,Math.max(1,s.lastUnlocked||1))}}catch(e){};
if(save.campaignSchema!==200){save.lastUnlocked=gg40LegacyLevel(save.lastUnlocked);save.lastPlayed=gg40LegacyLevel(save.lastPlayed||save.lastUnlocked);save.worldWeaponLevels=Array.isArray(save.worldWeaponLevels)?save.worldWeaponLevels.map(v=>Math.max(1,Math.min(40,1+Math.floor((Math.max(1,Number(v)||1)-1)*5.7)))):Array(10).fill(1);save.campaignSchema=200;}
/* Fase 45: limitar la campaña actual a 200 sin borrar el progreso guardado. */
save.lastUnlocked=Math.max(1,Math.min(201,Math.trunc(Number(save.lastUnlocked)||1)));
save.lastPlayed=Math.max(1,Math.min(200,Math.trunc(Number(save.lastPlayed)||1)));

function ggValidWorldWeaponLevels(value){
 const arr=Array.isArray(value)?value:[];
 return Array.from({length:10},(_,i)=>{const n=Number(arr[i]);return Number.isFinite(n)?Math.max(1,Math.min(GG40_MAX_POWER,Math.floor(n))):1});
}
save.worldWeaponLevels=ggValidWorldWeaponLevels(save.worldWeaponLevels);
function ggSavedWeaponForWorld(world){return ggValidWorldWeaponLevels(save.worldWeaponLevels)[world]||1}
function ggPersistWeaponOnVictory(world,weapon){
 save.worldWeaponLevels=ggValidWorldWeaponLevels(save.worldWeaponLevels);
 if(Number.isInteger(world)&&world>=0&&world<10)save.worldWeaponLevels[world]=Math.max(1,Math.min(GG40_MAX_POWER,Math.trunc(weapon)||1));
}
function persist(){try{localStorage.setItem('GG_UNIVERSO_V3',JSON.stringify(save))}catch(e){}}
const GG_PILOT_PROFILE_KEY='GG_GALACTICO_PILOT_PROFILE_V1';
function ggCleanPilotName(value){return String(value||'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,18)}
function ggLoadPilotProfile(){try{const p=JSON.parse(localStorage.getItem(GG_PILOT_PROFILE_KEY)||'null')||{};const runs=Array.isArray(p.runs)?p.runs.filter(x=>x&&Number.isFinite(Number(x.score))&&Number.isInteger(Number(x.level))).map(x=>({name:ggCleanPilotName(x.name)||'PILOTO',score:Math.max(0,Math.min(1e9,Math.floor(Number(x.score)))),level:Math.max(1,Math.min(200,Math.floor(Number(x.level)))),world:Math.max(0,Math.min(9,Math.floor(Number(x.world)||0))),won:!!x.won,at:Math.max(0,Math.floor(Number(x.at)||0))})).sort((a,b)=>b.score-a.score||a.at-b.at).slice(0,10):[];return {name:ggCleanPilotName(p.name),runs}}catch{return {name:'',runs:[]}}}
let ggPilotProfile=ggLoadPilotProfile();
function ggStorePilotProfile(){try{localStorage.setItem(GG_PILOT_PROFILE_KEY,JSON.stringify(ggPilotProfile))}catch(e){}}
function ggEscapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function ggPromptPilotName(after){window.GG_EXACT_UI?.hide();showModal('ELIGE TU NOMBRE DE PILOTO','Este nombre identificará tus partidas en el ranking guardado en este dispositivo.',[{label:'GUARDAR Y CONTINUAR',primary:true,onClick:()=>{const input=$('ggPilotNameInput'),name=ggCleanPilotName(input?.value);if(!name){$('ggPilotNameError').textContent='Escribe un nombre para continuar.';input?.focus();return;}ggPilotProfile.name=name;ggStorePilotProfile();$('pauseModal').classList.remove('gg-pilot-dialog');closeModal();if(after)after();else UI.screen('home');}}],'REGISTRO DE PILOTO');$('pauseModal').classList.add('gg-pilot-dialog');$('modalBody').innerHTML='<label class="gg-pilot-name-label" for="ggPilotNameInput">NOMBRE DE PILOTO<input id="ggPilotNameInput" maxlength="18" autocomplete="nickname" placeholder="Por ejemplo: Mikel" value="'+ggEscapeHtml(ggPilotProfile.name)+'"></label><p id="ggPilotNameError" class="gg-pilot-note" role="status">Se guarda solo en este navegador.</p>';$('ggPilotNameInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('modalButtons').querySelector('button')?.click()});setTimeout(()=>$('ggPilotNameInput')?.focus(),40)}

function ggShowPilotStatistics(){if(!ggPilotProfile.name){ggPromptPilotName(ggShowPilotStatistics);return;}window.GG_EXACT_UI?.hide();const missions=Math.min(200,Math.max(1,Number(save.lastUnlocked||1)));const cards=[['PIEZAS',Number(save.coins||0).toLocaleString('es-ES')],['MISIONES DESBLOQUEADAS',missions+' / 200'],['MEJOR PUNTUACIÓN',Number(save.highestScore||0).toLocaleString('es-ES')],['VICTORIAS',Number(save.wins||0).toLocaleString('es-ES')],['JEFES DERROTADOS',Number(save.bossWins||0).toLocaleString('es-ES')],['NIVELES PERFECTOS',Number(save.perfect||0).toLocaleString('es-ES')],['NAVES',save.ships.length+' / 60']];showModal('ESTADÍSTICAS DEL PILOTO','',[{label:'VER RANKING',primary:true,onClick:()=>{closeModal();ggShowMissionsRanking()}},{label:'IR A MISIONES',onClick:()=>{closeModal();ggOpenCurrentLevels()}},{label:'CERRAR',onClick:()=>{closeModal();UI.screen('home')}}],'CENTRO DE PILOTO');$('pauseModal').classList.add('gg-home-rank-dialog');$('modalBody').innerHTML='<div class="gg-statboard">'+cards.map(([label,value])=>'<div class="gg-stat-card"><small>'+label+'</small><strong>'+value+'</strong></div>').join('')+'</div><p class="gg-stat-note">Datos guardados en este dispositivo.</p>'}

function ggRequirePilotName(after){if(ggPilotProfile.name){after?.();return true;}ggPromptPilotName(after);return false;}
function ggRecordPilotRun(r,won){if(!r||!ggPilotProfile.name)return;ggPilotProfile.runs.push({name:ggPilotProfile.name,score:Math.max(0,Math.floor(Number(r.score)||0)),level:Math.max(1,Math.floor(Number(r.level)||1)),world:Math.max(0,Math.floor(Number(r.world)||0)),won:!!won,at:Date.now()});ggPilotProfile.runs.sort((a,b)=>b.score-a.score||a.at-b.at);ggPilotProfile.runs=ggPilotProfile.runs.slice(0,10);ggStorePilotProfile()}
function ggShowMissionsRanking(){if(!ggPilotProfile.name){ggPromptPilotName(ggShowMissionsRanking);return;}window.GG_EXACT_UI?.hide();const top=ggPilotProfile.runs.slice(0,10);const rows=top.length?top.map((r,i)=>'<div class="gg-rank-row"><b>'+(i+1)+'</b><span>'+ggEscapeHtml(r.name)+'</span><strong>'+r.score.toLocaleString('es-ES')+'</strong><small>NIVEL '+r.level+' · '+(r.won?'VICTORIA':'PARTIDA')+'</small></div>').join(''):'<p class="gg-rank-empty">Aún no hay partidas registradas. ¡Juega tu primera misión para estrenar el ranking!</p>';showModal('MISIONES Y RANKING','',[{label:'IR A MISIONES',primary:true,onClick:()=>{closeModal();ggOpenCurrentLevels()}},{label:'CAMBIAR NOMBRE',onClick:()=>{closeModal();ggPromptPilotName(ggShowMissionsRanking)}},{label:'CERRAR',onClick:()=>{closeModal();UI.screen('home')}}],'CENTRO DE PILOTO');$('pauseModal').classList.add('gg-home-rank-dialog');$('modalBody').innerHTML='<div class="gg-rank-summary"><div><small>PILOTO</small><b>'+ggEscapeHtml(ggPilotProfile.name)+'</b></div><div><small>PIEZAS</small><b>◈ '+Number(save.coins||0).toLocaleString('es-ES')+'</b></div><div><small>MISIONES</small><b>'+Math.min(200,Math.max(0,save.lastUnlocked-1))+' / 200</b></div><div><small>MEJOR PUNTUACIÓN</small><b>'+Number(save.highestScore||0).toLocaleString('es-ES')+'</b></div></div><h3 class="gg-rank-heading">MEJORES PARTIDAS · ESTE DISPOSITIVO</h3><div class="gg-rank-list">'+rows+'</div>'}
function ggChallengeFlags(state=save){return [state.wins>=30,state.bossWins>=10,state.highestScore>=30000,state.perfect>=15,state.lastUnlocked>=201]}
function ggNewShipRule(i,state=save){
 const offset=i-30,world=Math.floor(offset/3),slot=offset%3,localLevel=[7,14,20][slot],globalLevel=world*20+localLevel;
 const label=slot===0?'RECOMPENSA DEL SECTOR 1':slot===1?'RECOMPENSA DEL SECTOR 2':'JEFE FINAL';
 const unlocked=state.lastUnlocked>globalLevel;
 return {kind:'worldReward',price:0,world,available:unlocked,localLevel,globalLevel,label,short:`M${world+1} · N${localLevel}`,description:`Desbloqueo automático: completa ${WORLD_NAMES[world]} · nivel ${localLevel} (${label.toLowerCase()})`};
}
function ggSyncShipOwnership(){
 let owned=[...new Set((Array.isArray(save.ships)?save.ships:[]).map(Number).filter(v=>Number.isInteger(v)&&v>=0&&v<60))].sort((a,b)=>a-b);
 for(let i=0;i<5;i++)if(!owned.includes(i))owned.push(i);
 const flags=ggChallengeFlags(save);
 for(let i=0;i<5;i++)if(flags[i]&&!owned.includes(25+i))owned.push(25+i);
 for(let i=30;i<60;i++){
   const allowed=ggNewShipRule(i,save).available;
   if(allowed){if(!owned.includes(i))owned.push(i)}
   else { /* conservar las naves ya adquiridas en versiones anteriores */ }
 }
 save.ships=[...new Set(owned)].sort((a,b)=>a-b);
 if(!Number.isInteger(save.selected)||save.selected<0||save.selected>=60||!save.ships.includes(save.selected))save.selected=0;
 if(!Number.isInteger(save.lastPlayed)||save.lastPlayed<1||save.lastPlayed>200)save.lastPlayed=Math.min(200,Math.max(1,save.lastUnlocked));
}
ggSyncShipOwnership();
function shipStats(i){let cl=Math.floor((i%30)/6),up=save.upgrades[i]||{attack:0,armor:0,energy:0},variant=i%6;const speedBase=cl===0?345:cl===1?230:cl===2?285:cl===3?260:300,attackBase=cl===1?2.05:cl===4?1.9:cl===0?1.05:1.35,armorBase=cl===3?6:cl===1?5:cl===4?5:4;return {speed:Math.round(speedBase*(.94+variant*.024)),attack:Math.round(100*attackBase*(.94+variant*.022))/100,armor:Math.min(7,Math.max(3,armorBase+(variant%3===2?1:variant%3===0?-1:0))),upgrade:up,skill:cl}}
