function ggUnlockRule(i,state=save){
 if(i<5)return {kind:'initial',price:0,world:0,available:true,description:'Nave inicial'};
 if(i>=30&&i<60)return ggNewShipRule(i,state);
 if(i>=25){const labels=['30 misiones superadas','10 jefes derrotados','30.000 puntos en récord','15 misiones sin recibir impactos','Completar los 200 niveles'];const flags=ggChallengeFlags(state);return {kind:'challenge',price:0,world:9,available:flags[i-25],description:'Desafío: '+labels[i-25]};}
 const w=Math.floor((i-5)/2),price=700+i*135;
 return {kind:'planet',price,world:w,available:state.lastUnlocked>w*20,description:'Completa '+WORLD_NAMES[w]+' o compra por ◈'+price+' tras desbloquear el planeta'};
}
function ggBuyShip(i){
 if(!Number.isInteger(i)||i<5||i>24||save.ships.includes(i))return false;
 const rule=ggUnlockRule(i);
 if(!rule.available||save.coins<rule.price)return false;
 save.coins-=rule.price;save.ships.push(i);save.ships=[...new Set(save.ships)].sort((a,b)=>a-b);
 persist();return true;
}

