let gg28AnimationHandle=0, gg28StatusTimer=0;
function gg28AnimateStars(canvas, duration){
 const ctx=canvas.getContext('2d');if(!ctx)return;
 const dpr=Math.min(2,devicePixelRatio||1),width=innerWidth,height=innerHeight;
 canvas.width=Math.ceil(width*dpr);canvas.height=Math.ceil(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
 const stars=Array.from({length:145},(_,i)=>{
   const a=i*2.399963229728653,seed=((i*73+37)%149)/149;
   return {a,seed,brightness:.25+(i%7)/9};
 });
 const t0=performance.now(),centerX=width*.5,centerY=height*.5,maxRadius=Math.hypot(width,height)*.73;
 function frame(now){
  const t=Math.min(1,(now-t0)/duration);ctx.clearRect(0,0,width,height);
  if(t>.06&&t<.87){
   const visibility=Math.min(1,(t-.06)*4, (.87-t)*6);
   ctx.lineCap='round';
   for(const s of stars){
    const d=(s.seed*.9+t*1.85)%1;
    const radial=(.035+d*d*.95)*maxRadius;
    const length=Math.max(2,radial*(.022+t*.14));
    const ca=Math.cos(s.a),sa=Math.sin(s.a);
    const x=centerX+ca*radial,y=centerY+sa*radial;
    ctx.strokeStyle=`rgba(${s.seed>.7?'225,245,255':'90,187,255'},${Math.min(.82,s.brightness*.75*visibility)})`;
    ctx.lineWidth=.75+2*d;
    ctx.beginPath();ctx.moveTo(x-ca*length,y-sa*length);ctx.lineTo(x,y);ctx.stroke();
   }
  }
  if(t<.96&&document.getElementById('planetZoom').classList.contains('gg28-flight'))gg28AnimationHandle=requestAnimationFrame(frame);
  else ctx.clearRect(0,0,width,height);
 }
 gg28AnimationHandle=requestAnimationFrame(frame);
}
