   const phase=clamp((e.age-(e.gg57MorphAt||0))/1.6,0,1),smooth=phase*phase*(3-2*phase);
   const previous=ggFormationSlot(e.gg57PatternFrom,i,n);
   q[0]=previous[0]*(1-smooth)+q[0]*smooth;
   q[1]=previous[1]*(1-smooth)+q[1]*smooth;
