 // Movimiento deliberadamente distinto para cada una de las 36 combinaciones.
 const s=Math.sin(t*.8+(e.group||0)*.31),c=Math.cos(t*.7+(e.group||0)*.21);
 // Cada escuadrón ejecuta la coreografía declarada por su formación.
