 if(id===1){for(let s of [-1,0,1]){const n=projectiles.length;shot(x+s*15,y,s*110,-540,true,'homingMissile','#ffe779',7,28,'tracking');if(projectiles.length>n)projectiles[projectiles.length-1].weaponArt=8;}}
