/* Combate de producción: siete familias de tiro, diferenciadas por mundo y perfil.
  El director previo administra avisos, cadencias y el tope de proyectiles. */
const GG_ENEMY_ATTACK_FAMILIES=['lanza','tirador','abanico','ondulante','fragmentador','rastreador','acelerador'];
function fireEnemy(e,isBoss=false){window.GG_AUDIO_V2?.sfx('enemy');
 const uid=e.world*7+e.type,signature=GG_ATTACK_SIGNATURES[uid];
 if(!run||!signature)return;
 if(e.gg58New!==undefined){gg58ShootEnemy(e);return;}
 const x=e.x,y=e.y+20,early=e.world===0&&run.local<=10;
 const profile=ENEMY_GUN_PROFILES[uid];const speed=(early?PHASE15.firstFiveShotSpeed:profile.shotSpeed*signature.velocidad*(1+Math.min(8,profile.variation)*.008))*difficulty().speed;
 const damage=early?1:signature.damage;
 const family=GG_ENEMY_ATTACK_FAMILIES[e.type];GG_COMBAT_TELEMETRY.shotsByFamily[e.type]++;
 const rounds=early?(run.local<=5?2:3):Math.min(e.world<=2?3:e.world<=6?4:5,Math.max(2,signature.pulsos+(run.world>=5?1:0)));
 const worldShift=signature.desfase*.0005;const spreadScale=clamp(signature.apertura/50*.6+profile.scatter*.4,.62,1.33);
 const aim=Math.atan2(Math.max(65,run.py-y),run.px-x);const patternBend=(signature.patron%3-1)*.022;
 // The first five missions teach avoiding straight shots before complex patterns.
 if(early){
    // Enseñanza gradual: cada clase tiene su trayectoria propia desde el nivel 1.
    // Sin homing ni fragmentación durante los primeros siete niveles del mundo 1.
    const fireIntro=(a,behavior='normal',factor=1,offset=0)=>{
      a=clamp(a,.20,Math.PI-.20);
      shot(x+offset,y,Math.cos(a)*speed*factor,Math.sin(a)*speed*factor,false,signature.proyectil,GG_ATTACK_UI_COLORS[e.type],5,1,behavior,uid%20,ggEnemyArtRegular(e.world,e.type));
    };
    const teach=run.local<=5;
    if(e.type===0){fireIntro(Math.PI/2,'normal',.88);}
    else if(e.type===1){fireIntro(aim,'normal',.90);}
    else if(e.type===2){for(let k of [-1,1])fireIntro(aim+k*(teach?.12:.17),'normal',.84);}
    else if(e.type===3){fireIntro(aim-.09,teach?'normal':'wave',.86);if(!teach)fireIntro(aim+.09,'normal',.82);}
    else if(e.type===4){fireIntro(aim,run.local>=8?'split':'normal',.77);}
    else if(e.type===5){fireIntro(aim,run.local>=9?'homing':'normal',.75);}
    else{fireIntro(aim-.10,teach?'normal':'accelerate',.75);if(!teach)fireIntro(aim+.10,'normal',.75);}
    return;
  }
 const emit=(angle,behavior='normal',scale=1,offset=0,radius=6)=>{
   const safeAngle=clamp(angle,.18,Math.PI-.18),vx=Math.cos(safeAngle)*speed*scale,vy=Math.sin(safeAngle)*speed*scale;
   shot(x+offset,y,vx,vy,false,signature.proyectil,GG_ATTACK_UI_COLORS[e.type],radius,damage,behavior,uid%20,ggEnemyArtRegular(e.world,e.type,signature.proyectil,behavior));
 };
 if(family==='lanza'){
   // Precise, predominantly vertical fire with a world-specific lateral bias.
   for(let i=0;i<Math.min(2,rounds);i++)emit(aim+worldShift+(i-.5)*.12*spreadScale+patternBend,'normal',1,i*12-6,5);
 }else if(family==='tirador'){
   // Targeted shot: the formation warning gives the player time to change position.
   emit(aim-.09+patternBend,'normal',.95,-8,6);
    if(rounds>=2)emit(aim+.09+patternBend,'normal',.92,8,5);
    if(rounds>=3&&e.world>=4)emit(aim,'normal',.84,0,5);
 }else if(family==='abanico'){
   // A narrow V, with openings between adjacent enemies' shots.
   for(let i=0;i<rounds;i++)emit(aim+(i-(rounds-1)/2)*(.17+e.world*.006)*spreadScale+worldShift+patternBend,'normal',.89,0,5);
 }else if(family==='ondulante'){
   for(let i=0;i<Math.min(3,rounds);i++)emit(aim+(i-1)*.21*spreadScale+patternBend,'wave',.84,(i-1)*8,6);
 }else if(family==='fragmentador'){
   // Fragments activate only after the early worlds; bullets always obey the cap.
   for(let i=0;i<Math.min(2,rounds);i++)emit(aim+(i-.5)*.18*spreadScale+patternBend,e.world>=2?'split':'normal',.76,(i-.5)*12,7);
 }else if(family==='rastreador'){
   emit(aim+patternBend,'homing',.77,0,7);
   if(rounds>=2)emit(aim+worldShift+.13,'normal',.88,9,5);
 }else{
   for(let i=0;i<Math.min(3,rounds);i++)emit(aim+(i-(Math.min(3,rounds)-1)/2)*.14*spreadScale+patternBend,'accelerate',.65,(i-1)*5,5);
 }
}

/* Every destructible boss module has an actual hitbox and attack source.
   Core attacks are mitigated until the player dismantles the emitters. */
function ggHitBoss(b,x,y,damage,source='projectile'){
 if(!b||damage<=0)return false;
 const part=(b.parts||[]).find(p=>p.alive&&Math.hypot(b.x+p.offsetX-x,b.y+p.offsetY-y)<p.r+4);
 if(part){
   part.hp-=damage;b.hit=.18;run.score+=10;
   if(part.hp<=0){
     part.hp=0;part.alive=false;part.disabledAt=run.elapsed;b.destroyedParts++;
     b.hp=Math.max(0,b.hp-Math.round(b.maxHp*.058));
     for(let i=0;i<22;i++)createFx(b.x+part.offsetX,b.y+part.offsetY,COLORS[b.world]);
     announce('TORRETA DESTRUIDA · DISPAROS REDUCIDOS',1.45);tone(150,.14);window.GG_AUDIO_V2?.sfx('turret');
   }
   return true;
 }
 // Las partes están fuera del centro de la nave; el núcleo tiene una colisión propia.
 if(Math.abs(b.x-x)<b.r&&Math.abs(b.y-y)<b.r*.95){
   const shielded=b.parts?.some(p=>p.alive);
   const exposed=shielded?clamp(.38+b.destroyedParts*.13,.38,.86):1.18;
   b.hp-=damage*exposed;b.hit=.14;run.score+=2;
   return true;
 }
 return false;
}
function fireBoss(b){
 const st=b.stage,p=b.profile,pattern=p.patterns[st],spd=(180+b.world*10+run.local*.65+st*15)*difficulty().speed,c=COLORS[b.world];
 const points=(b.parts||[]).filter(part=>part.alive).map(part=>[b.x+part.offsetX,b.y+part.offsetY]);
 const intact=points.length,total=b.parts?.length||1;const corePoints=points.length?points:[[b.x,b.y+35]];let emitted=0;
 const fire=(x,y,vx,vy,kind='orb',radius=6,behavior='normal',id=null)=>{
   // Destroyed emitters suppress part of the barrage, while the exposed core still fights.
   emitted++;if(intact<total && emitted%(intact?3:2)===0)return;
   shot(x,y,vx,vy,false,kind,c,radius,1,behavior,id===null?(b.world*2+b.type*3+st*5)%20:id,ggEnemyArtBoss(pattern,st,b.type,b.world,kind,behavior));
 };
 const target=(x,y,s=spd)=>{let a=Math.atan2(run.py-y,run.px-x);return[Math.cos(a)*s,Math.sin(a)*s]};
 if(pattern==='abanico')for(let i=-4;i<=4;i++)fire(b.x,b.y+50,i*50,spd,'needle',6);
 if(pattern==='anillo')for(let i=0;i<12;i++){let a=i*TAU/12+b.age*.22;fire(b.x,b.y+32,Math.sin(a)*spd,Math.cos(a)*spd,'orb',7)}
 if(pattern==='rastreadores')for(let [x,y] of corePoints){let [vx,vy]=target(x,y);fire(x,y,vx,vy,'orb',8,'homing')}
 if(pattern==='cortina')for(let i=-4;i<=4;i++)fire(b.x+i*39,b.y+45,Math.sin(i)*28,spd,'needle',7,'accelerate');
 if(pattern==='tenaza')for(let side of [-1,1])for(let i=0;i<5;i++)fire(b.x+side*63,b.y+30,side*(i*24-42),spd+i*12,'spike',6);
 if(pattern==='espiral')for(let i=0;i<12;i++){let a=i*TAU/12+b.age*1.4;fire(b.x,b.y+30,Math.sin(a)*spd,Math.cos(a)*spd,'orb',6,'wave')}
 if(pattern==='rayos')for(let [x,y] of corePoints){let [vx,vy]=target(x,y,spd*1.22);fire(x,y,vx,vy,'laser',7,'normal')}
 if(pattern==='órbitas')for(let i=0;i<10;i++){let a=i*TAU/10;fire(b.x,b.y+45,Math.cos(a)*spd*.66,Math.sin(a)*spd*.66,'ring',7,'wave')}
 if(pattern==='cargados')for(let i=-2;i<=2;i++){let [vx,vy]=target(b.x+i*35,b.y+45,spd*.66);fire(b.x+i*35,b.y+45,vx,vy,'orb',11,'accelerate')}
 if(pattern==='oleada')for(let i=0;i<9;i++)fire(b.x+(i-4)*25,b.y+45,Math.sin(i*.65)*102,spd,'orb',6,'wave');
 if(pattern==='aceleración')for(let i=-3;i<=3;i++)fire(b.x+i*30,b.y+45,i*39,spd*.72,'needle',7,'accelerate');
 if(pattern==='serpiente')for(let i=-3;i<=3;i++)fire(b.x+i*27,b.y+45,0,spd,'spike',6,'wave');
 if(pattern==='minas')for(let [x,y] of corePoints)for(let i=-1;i<=1;i++)fire(x+i*17,y,i*65,spd*.5,'orb',11,'brake');
 if(pattern==='fragmentación')for(let i=-2;i<=2;i++)fire(b.x+i*37,b.y+45,i*27,spd*.8,'orb',10,'split');
 if(pattern==='cruzada')for(let i=-3;i<=3;i++){fire(b.x-70,b.y+40,90+i*36,spd,'needle',6);fire(b.x+70,b.y+40,-90+i*36,spd,'needle',6)}
 if(pattern==='doble láser')for(let side of [-1,1]){let x=b.x+side*58,[vx,vy]=target(x,b.y+50,spd*1.1);fire(x,b.y+50,vx,vy,'laser',9)}
 // Cada módulo activo aporta su propio ataque en las fases avanzadas.
 // Al desactivarlo cesa ese disparo, sin eliminar el ataque central.
 if(b.stage>0&&points.length){
   const modules=Math.min(points.length,b.type===4?3:2);
   for(let i=0;i<modules;i++){
     const [x,y]=points[(i+b.stage)%points.length];
     const [vx,vy]=target(x,y,spd*(b.stage===2?.80:.68));
     fire(x,y,vx,vy,b.type===4?'spike':'orb',5,'normal');
   }
 }
} 
function hurtEnemy(e,dmg){if(!e||e.hp<=0||dmg<=0)return false;GG_COMBAT_TELEMETRY.hitsEnemy++;e.hp-=dmg;e.hit=.16;if(e.hp<=0){f14LeaderDestroyed(e);for(let i=0;i<14;i++)createFx(e.x,e.y,COLORS[run.world]);tone(170,.08);window.GG_AUDIO_V2?.sfx('explosion');run.score+=90+e.type*15;run.earned+=2+Math.floor(e.type/2);run.killCount++;GG_COMBAT_TELEMETRY.enemyKills++;gg42OnKill(e);dropItem(e.x,e.y);return true}return false}
function hurtPlayer(damage=1){if(!run||run.inv>0)return;
 const impact=clamp(Math.round(Number(damage)||1),1,3);run.inv=GAME_RULES.lossProtection;run.hitCount++;GG_COMBAT_TELEMETRY.hitsPlayer++;
 let remaining=impact;while(remaining>0){remaining--;
  if(run.shield>0){run.shield--}
  else if(run.weapon>1){run.weapon=Math.max(1,run.weapon-1)}
   else{run.hp=Math.max(0,run.hp-1);run.weapon=1;break;}
 }
 announce(run.hp<=0?'NAVE DESTRUIDA':impact>1?'IMPACTO FUERTE · -'+impact+' DEFENSA':'IMPACTO · ESCUDO/POTENCIA/VIDA',1.4);
 for(let i=0;i<22;i++)createFx(run.px,run.py,'#fbe9aa');tone(100,.23);window.GG_AUDIO_V2?.sfx('hurt');updateHud();if(run.hp<=0)finish(false)}
function finish(won){if(!run||run.done)return;window.GG_AUDIO_V2?.sfx(won?'victory':'defeat');ggRecordPilotRun(run,won);run.done=true;paused=true;playing=false;save.coins+=run.earned+(won?150+run.local*7:0);save.highestScore=Math.max(save.highestScore,run.score);const ownedBefore=new Set(save.ships);if(won){ggPersistWeaponOnVictory(run.world,run.weapon);save.wins++;if(run.hitCount===0)save.perfect++;if(run.bossLevel)save.bossWins++;if(run.level===save.lastUnlocked)save.lastUnlocked=Math.min(201,run.level+1);save.lastPlayed=Math.min(200,run.level===save.lastUnlocked-1?run.level+1:run.level);if(run.local===20){let w=run.world,nums=[5+w*2,6+w*2];for(let n of nums)if(n<25&&!save.ships.includes(n))save.ships.push(n)}}ggSyncShipOwnership();const challenges=save.ships.filter(i=>!ownedBefore.has(i)).map(i=>SHIPS[i]);persist();updateHud();let earned=run.earned+(won?150+run.local*7:0);showModal(won?'¡MISIÓN COMPLETADA!':'MISIÓN FALLIDA',`${WORLD_NAMES[run.world]} · Nivel ${run.local}. Puntos: ${run.score}. Monedas obtenidas: ${earned}. Bonificaciones tácticas: ${run.gg42Bonus||0} monedas. Interceptores abatidos: ${run.gg42Intercepts||0}. Eventos de sector: ${run.gg56EventsSeen||0}. Desafíos ganados: ${run.gg56ChallengesWon||0}.${challenges.length?' Naves desbloqueadas: '+challenges.join(', ')+'.':''}`,[{label:won?'▶ SIGUIENTE NIVEL':'↻ REINTENTAR',primary:true,onClick:()=>{closeModal();if(won){let next=Math.min(200,run.level+1);if(run.level>=200)UI.screen('galaxy');else start(next)}else start(run.level)}},{label:'🪐 MAPA DE NIVELES',onClick:()=>{closeModal();playing=false;UI.screen('levels')}},{label:'🚀 HANGAR',onClick:()=>{closeModal();hangarFrom='levels';UI.screen('hangar')}}],won?'VICTORIA':'DERROTA')}
function gg34FillCells(id,count,active,kind=''){
 const el=document.getElementById(id);if(!el)return;
 const n=Math.max(0,Math.min(12,Math.floor(Number(count)||0))),on=Math.max(0,Math.min(n,Math.floor(Number(active)||0)));
 const stamp=`${n}/${on}/${kind}`;if(el.dataset.state===stamp)return;
 el.dataset.state=stamp;el.innerHTML=Array.from({length:n},(_,i)=>`<span class="${i<on?'active':''}" aria-hidden="true"></span>`).join('');
}
function gg34UpdateHud(r,activeBoss){
 gg34FillCells('gg34WeaponCells',5,gg40WeaponInfo(r.weapon).stage,'weapon-'+gg40WeaponInfo(r.weapon).family);
 gg34FillCells('gg34ShieldCells',6,Math.min(6,r.shield),'shield');
 gg34FillCells('gg34WaveCells',r.waveCount,Math.max(1,Math.min(r.waveCount,r.wave)),'wave');
 const lifeIcons=document.getElementById('gg34LifeIcons');
 if(lifeIcons)lifeIcons.textContent=Array.from({length:r.maxHp},(_,i)=>i<r.hp?'◆':'◇').join(' ');
 const energy=document.getElementById('gg34EnergyLabel');if(energy)energy.textContent=Math.round(r.energy)+'%';
 const score=document.getElementById('gg34ScoreMeter');if(score)score.style.width=((r.score%1000)/10)+'%';
 const world=document.getElementById('gg34World');if(world)world.textContent='MUNDO '+(r.world+1);
 const hint=document.getElementById('gg34WeaponWorldHint');if(hint)hint.textContent='PROGRESO POR PLANETA · '+WORLD_NAMES[r.world].toUpperCase();
}
/* FASE 37 · El nuevo cockpit lee el estado real del juego; sin estadísticas simuladas. */
function gg37UpdateHud(r,activeBoss){
 const get=id=>document.getElementById(id);
 const put=(id,value)=>{const n=get(id);if(n&&n.textContent!==String(value))n.textContent=String(value)};
 put('gg37Sector',String(r.world+1).padStart(2,'0')+' // 10');
 put('gg37Planet',WORLD_NAMES[r.world].toUpperCase());
 put('gg37Level','MISIÓN '+String(r.local).padStart(2,'0')+' / 20');
 const ratio=r.maxHp>0?Math.round(100*r.hp/r.maxHp):0;
 put('gg37HullPct',ratio+'%');
 put('gg37ShipName',SHIPS[save.selected]||'NAVE');
 const ship=get('gg37ShipImage'),shipUrl=ART.naves[save.selected];
 if(ship&&shipUrl&&ship.dataset.ship!==String(save.selected)){ship.dataset.ship=String(save.selected);ship.src=ggAsset(shipUrl);}
 const hull=get('gg34LifeIcons');
 if(hull){const sig=r.hp+'/'+r.maxHp;if(hull.dataset.state!==sig){hull.dataset.state=sig;hull.innerHTML=Array.from({length:r.maxHp},(_,i)=>'<span class="'+(i<r.hp?'alive':'lost')+'" aria-hidden="true">◆</span>').join('');hull.setAttribute('aria-label',r.hp+' vidas de '+r.maxHp)}}
 const cockpit=get('cockpitPanel');if(cockpit)cockpit.classList.toggle('gg37-critical',r.hp<=1);
 put('gg37Ability',r.energy>=99.5?'HABILIDAD DISPONIBLE':r.specialKind?'SISTEMA ACTIVADO':'RECARGANDO ENERGÍA');
 const missileReady=r.secondary>=0&&r.ammo[r.secondary]>0;
 put('gg37MissileState',missileReady?'● EQUIPADA':'○ VACÍA');
 put('gg37SecondaryHint',missileReady?'DISPARO SECUNDARIO LISTO':'RECOGE UN POWER-UP');
 const icon=get('cockpitSecondaryIcon');
 if(icon)icon.classList.toggle('gg37-loaded',missileReady);
 const waveName=r.formationState?.name||'';
 put('gg37ThreatName',activeBoss?'FASE '+(activeBoss.stage+1)+' / 3 · '+activeBoss.parts.filter(p=>p.alive).length+' TORRETAS':waveName.toUpperCase()||'ESCANEANDO FORMACIÓN ENEMIGA');
 const bar=get('gg37BossBar'),gauge=get('gg37BossGauge');
 if(gauge)gauge.hidden=!activeBoss;
 if(activeBoss){
   put('gg37BossName',BOSSES[r.world][activeBoss.type].toUpperCase());
   const pct=Math.max(0,Math.min(100,Math.round(100*activeBoss.hp/activeBoss.maxHp)));
   put('gg37BossPct',pct+'%');if(bar)bar.style.width=pct+'%';
 }
}
